#include <iostream>
#include <string>
using namespace std;

int main() {
    string dns, line;
    getline(cin, dns);
    while (getline(cin, line)) {
        if (line.empty())
            continue;
        cout << (line == dns ? "ok" : "leak") << "\n";
    }
